class Solution {
    private final Map<Integer,Integer> height=new HashMap<>(),answer=new HashMap<>();
    private int measure(TreeNode node){
        if(node==null)return 0;
        int value=1+Math.max(measure(node.left),measure(node.right));
        height.put(node.val,value);
        return value;
    }
    private void reroot(TreeNode node,int depth,int rest){
        if(node==null)return;
        answer.put(node.val,rest);
        reroot(node.left,depth+1,Math.max(rest,depth+(node.right==null?0:height.get(node.right.val))));
        reroot(node.right,depth+1,Math.max(rest,depth+(node.left==null?0:height.get(node.left.val))));
    }
    public int[] treeQueries(TreeNode root,int[] queries){
        measure(root);
        reroot(root,0,0);
        int[] result=new int[queries.length];
        for(int i=0;i<queries.length;i++)result[i]=answer.get(queries[i]);
        return result;
    }
}

code.kotlin:
class Solution {
    private val height=HashMap<Int,Int>();
    private val answer=HashMap<Int,Int>();
    private fun measure(node:TreeNode?):Int{
        if(node==null)return 0;
        val value=1+maxOf(measure(node.left),measure(node.right));
        height[node.`val`]=value;
        return value
    }
    private fun reroot(node:TreeNode?,depth:Int,rest:Int){
        if(node==null)return;
        answer[node.`val`]=rest;
        reroot(node.left,depth+1,maxOf(rest,depth+(node.right?.let{
            height[it.`val`]
        }?:0)));
        reroot(node.right,depth+1,maxOf(rest,depth+(node.left?.let{
            height[it.`val`]
        }?:0)))
    }
    fun treeQueries(root:TreeNode?,queries:IntArray):IntArray{
        measure(root);
        reroot(root,0,0);
        return IntArray(queries.size){
            answer[queries[it]]!!
        }
    }
}

